-- Additive v30 -> v31: native named equipment properties and per-level policy.
-- Apply only to the stopped owned package, after a verified full checkpoint.
SET @auriga_target_constraint=(SELECT CONSTRAINT_NAME FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA='protos' AND TABLE_NAME='bonus_definition' AND CHECK_CLAUSE LIKE '%target_kind%' LIMIT 1);
SET @auriga_target_ddl=IF(@auriga_target_constraint IS NULL,'DO 0',CONCAT('ALTER TABLE protos.bonus_definition DROP CONSTRAINT `',REPLACE(@auriga_target_constraint,'`','``'),'`'));
PREPARE auriga_target_change FROM @auriga_target_ddl;
EXECUTE auriga_target_change;
DEALLOCATE PREPARE auriga_target_change;
ALTER TABLE protos.bonus_definition ADD CONSTRAINT ck_bonus_equipment_target CHECK(target_kind BETWEEN 1 AND 25);
ALTER TABLE protos.refinement_level
 ADD COLUMN IF NOT EXISTS minimum_level SMALLINT UNSIGNED NULL,
 ADD COLUMN IF NOT EXISTS buy_amount BIGINT UNSIGNED NULL,
 ADD COLUMN IF NOT EXISTS sell_amount BIGINT UNSIGNED NULL;
ALTER TABLE protos.refinement_level ADD CONSTRAINT IF NOT EXISTS ck_refinement_level_economy CHECK((buy_amount IS NULL OR buy_amount<=9223372036854775807) AND (sell_amount IS NULL OR sell_amount<=9223372036854775807));
ALTER TABLE protos.accessory_socket_grade ADD COLUMN IF NOT EXISTS truncate_bonus TINYINT UNSIGNED NOT NULL DEFAULT 0 CHECK(truncate_bonus IN(0,1));
SET @auriga_weight_constraint=(SELECT CONSTRAINT_NAME FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA='protos' AND TABLE_NAME='attribute_candidate' AND CHECK_CLAUSE LIKE '%weight%' LIMIT 1);
SET @auriga_weight_ddl=IF(@auriga_weight_constraint IS NULL,'DO 0',CONCAT('ALTER TABLE protos.attribute_candidate DROP CONSTRAINT `',REPLACE(@auriga_weight_constraint,'`','``'),'`'));
PREPARE auriga_weight_change FROM @auriga_weight_ddl;
EXECUTE auriga_weight_change;
DEALLOCATE PREPARE auriga_weight_change;
ALTER TABLE protos.attribute_candidate ADD CONSTRAINT ck_attribute_retained_weight CHECK(weight<=1000000);
